/**
 * Resolve a URL to a brand glyph by walking the hostname from the most
 * specific label set to the least, so mail.google.com beats google.com.
 */
export function brandFor(url: string): BrandMark | null {
  let host: string
  try {
    host = new URL(url).hostname.toLowerCase()
  } catch {
    return null
  }
  if (host.startsWith('www.')) host = host.slice(4)

  const labels = host.split('.')
  for (let i = 0; i < labels.length - 1; i++) {
    const slug = HOST_BRANDS[labels.slice(i).join('.')]
    if (slug) return BRAND_MARKS[slug] ?? null
  }
  return null
}
